![medium](https://www.gstatic.com/codereviewagent/medium-priority.svg)

Update `loadRenderer` to use the dynamically resolved package paths via `require.resolve`. This eliminates the need for manual directory existence checks and hardcoded candidate roots, making the renderer loading process robust and portable.

```javascript
async function loadRenderer() {
  let pdfjsDistPath;
  let napiCanvasPath;
  try {
    pdfjsDistPath = path.dirname(require.resolve('pdfjs-dist/package.json'));
    napiCanvasPath = path.dirname(require.resolve('@napi-rs/canvas/package.json'));
  } catch (error) {
    throw new Error('pdfjs-dist and @napi-rs/canvas are required for MS page screenshot rendering: ' + error.message);
  }
  const pdfjs = await import(pathToFileURL(path.join(pdfjsDistPath, 'legacy/build/pdf.mjs')).href);
  const canvas = await import(pathToFileURL(path.join(napiCanvasPath, 'index.js')).href);
  if (canvas.DOMMatrix && !globalThis.DOMMatrix) globalThis.DOMMatrix = canvas.DOMMatrix;
  if (canvas.ImageData && !globalThis.ImageData) globalThis.ImageData = canvas.ImageData;
  if (canvas.Path2D && !globalThis.Path2D) globalThis.Path2D = canvas.Path2D;
  const pdfjsVersion = JSON.parse(
    fs.readFileSync(path.join(pdfjsDistPath, 'package.json'), 'utf8'),
  ).version;
  // Trailing separator is required: pdfjs concatenates the font filename onto this URL.
  const standardFontDataUrl = `${pathToFileURL(path.join(pdfjsDistPath, 'standard_fonts')).href}/`;
  const cMapUrl = `${pathToFileURL(path.join(pdfjsDistPath, 'cmaps')).href}/`;
  return { pdfjs, canvas, pdfjsVersion, standardFontDataUrl, cMapUrl };
}
