+      pushError(errors, 'artifact_boundary_violation', `artifact_boundary.${field}`, `${field} must be true`);
+    }
+  }
+  for (const field of [
+    'screenshot_binaries_committed_to_git',
+    'crops_generated',
+    'public_static_assets_generated',
+    'external_ocr_vlm_or_model_call_performed',
+    'ocr_used',
+    'external_model_used',
+    'production_supabase_mutation_performed',
+    'rag_reindex_performed',
+    'vector_mutation_performed',
+    'production_side_effects_performed',
+    'frontend_integration_performed',
+    'student_display_approval_claimed',
+    'visual_qa_pass_claimed',
+  ]) {
+    if (manifest?.artifact_boundary?.[field] !== false) {
+      pushError(errors, 'artifact_boundary_violation', `artifact_boundary.${field}`, `${field} must be false`);
+    }
+  }
+
+  const zeroSideEffectFields = [
+    'production_supabase_mutation_count',
+    'remote_supabase_mutation_count',
+    'production_rag_reindex_count',
+    'vector_mutation_count',
+    'external_ocr_vlm_model_call_count',
