+
+async function loadRenderer() {
+  const nodeModulesRoot = NODE_MODULES_CANDIDATE_ROOTS
+    .map((resolve) => resolve())
+    .find((candidate) => fs.existsSync(path.join(candidate, 'pdfjs-dist')));
+  if (!nodeModulesRoot) {
+    throw new Error('pdfjs-dist and @napi-rs/canvas are required for MS page screenshot rendering');
+  }
+  const pdfjs = await import(pathToFileURL(path.join(nodeModulesRoot, 'pdfjs-dist/legacy/build/pdf.mjs')).href);
+  const canvas = await import(pathToFileURL(path.join(nodeModulesRoot, '@napi-rs/canvas/index.js')).href);
+  if (canvas.DOMMatrix && !globalThis.DOMMatrix) globalThis.DOMMatrix = canvas.DOMMatrix;
+  if (canvas.ImageData && !globalThis.ImageData) globalThis.ImageData = canvas.ImageData;
+  if (canvas.Path2D && !globalThis.Path2D) globalThis.Path2D = canvas.Path2D;
+  const pdfjsVersion = JSON.parse(
+    fs.readFileSync(path.join(nodeModulesRoot, 'pdfjs-dist/package.json'), 'utf8'),
+  ).version;
+  // Trailing separator is required: pdfjs concatenates the font filename onto this URL.
+  const standardFontDataUrl = `${pathToFileURL(path.join(nodeModulesRoot, 'pdfjs-dist/standard_fonts')).href}/`;
+  const cMapUrl = `${pathToFileURL(path.join(nodeModulesRoot, 'pdfjs-dist/cmaps')).href}/`;
+  return { pdfjs, canvas, pdfjsVersion, standardFontDataUrl, cMapUrl };
+}
+
+/**
+ * Render every unique page target to the controlled package root.
+ * Returns a Map keyed by dedupe_key holding either render metadata or an exact blocker reason.
+ */
+export async function renderControlledPackage({ root, targets }) {
+  const { pdfjs, canvas, standardFontDataUrl, cMapUrl } = await loadRenderer();
+  const packageDir = path.join(root, CONTROLLED_PACKAGE_ROOT);
+  fs.mkdirSync(packageDir, { recursive: true });
+
+  const byDedupeKey = new Map();
+  const byDocument = new Map();
+  for (const target of targets) {
+    const group = byDocument.get(target.ms_document_id) ?? [];
+    group.push(target);
+    byDocument.set(target.ms_document_id, group);
+  }
+
+  for (const [, group] of [...byDocument.entries()].sort((left, right) => compareString(left[0], right[0]))) {
+    const { ms_file_path: msFilePath, source_pdf_sha256: sourcePdfSha256 } = group[0];
+    const pdfPath = resolvePath(root, msFilePath);
+
+    if (!fs.existsSync(pdfPath)) {
+      for (const target of group) {
+        byDedupeKey.set(target.dedupe_key, {
+          blocker_reason_code: 'source_pdf_missing',
+          blocker_reason: `source MS PDF is missing at ${msFilePath}`,
+        });
+      }
+      continue;
+    }
+    const pdfBytes = fs.readFileSync(pdfPath);
+    const observedSha256 = sha256Buffer(pdfBytes);
+    if (observedSha256 !== sourcePdfSha256) {
+      for (const target of group) {
+        byDedupeKey.set(target.dedupe_key, {
+          blocker_reason_code: 'source_pdf_sha256_mismatch',
+          blocker_reason: `source MS PDF hash drifted: expected ${sourcePdfSha256}, observed ${observedSha256}`,
+        });
+      }
+      continue;
+    }
+
+    let document;
+    try {
+      document = await pdfjs.getDocument({
+        data: new Uint8Array(pdfBytes),
+        disableFontFace: RENDER_CONFIG.disable_font_face,
+        disableWorker: true,
+        useSystemFonts: RENDER_CONFIG.use_system_fonts,
+        isEvalSupported: RENDER_CONFIG.is_eval_supported,
+        standardFontDataUrl,
+        cMapUrl,
+        cMapPacked: true,
+      }).promise;
+    } catch (error) {
+      for (const target of group) {
+        byDedupeKey.set(target.dedupe_key, {
+          blocker_reason_code: 'source_pdf_open_failed',
+          blocker_reason: `pdfjs could not open ${msFilePath}: ${error.message}`,
+        });
+      }
+      continue;
+    }
+
+    for (const target of group) {
+      const pageNumber = target.ms_page_locator.pdf_page_number_one_based;
+      if (pageNumber < 1 || pageNumber > document.numPages) {
+        byDedupeKey.set(target.dedupe_key, {
+          blocker_reason_code: 'pdf_page_index_out_of_range',
