To prevent memory leaks and ensure proper resource cleanup, wrap the page rendering loop in a `try...finally` block to guarantee `document.destroy()` is called. Similarly, wrap the individual page rendering in a `try...finally` block to guarantee `page.cleanup()` is executed even if rendering or file writing throws an error.

```javascript
    try {
      for (const target of group) {
        const pageNumber = target.ms_page_locator.pdf_page_number_one_based;
        if (pageNumber < 1 || pageNumber > document.numPages) {
          byDedupeKey.set(target.dedupe_key, {
            blocker_reason_code: 'pdf_page_index_out_of_range',
            blocker_reason: `pdf page ${pageNumber} is out of range for ${msFilePath} (numPages=${document.numPages})`
          });
          continue;
        }
        try {
          const page = await document.getPage(pageNumber);
          try {
            const viewport = page.getViewport({ scale: RENDER_CONFIG.render_scale });
            const width = Math.ceil(viewport.width);
            const height = Math.ceil(viewport.height);
            const renderCanvas = canvas.createCanvas(width, height);
            const context = renderCanvas.getContext('2d');
            context.fillStyle = RENDER_CONFIG.background_fill;
            context.fillRect(0, 0, width, height);
            await page.render({ canvasContext: context, viewport }).promise;

            const buffer = await renderCanvas.encode('png');
            const fileName = assetFileName(target.ms_document_id, sourcePdfSha256, pageNumber);
            fs.writeFileSync(path.join(packageDir, fileName), buffer);
            byDedupeKey.set(target.dedupe_key, {
              output_image_sha256: sha256Buffer(buffer),
              image_width_px: width,
              image_height_px: height,
              byte_size: buffer.length
            });
          } finally {
            page.cleanup();
          }
        } catch (error) {
          byDedupeKey.set(target.dedupe_key, {
            blocker_reason_code: 'page_render_failed',
            blocker_reason: `pdfjs failed to render page ${pageNumber} of ${msFilePath}: ${error.message}`
          });
        }
      }
    } finally {
      await document.destroy();
    }
