![medium](https://www.gstatic.com/codereviewagent/medium-priority.svg)

When recomputing summary statistics, preserve the raw count of all elements for the total count, but filter the array to record-only entries before performing property-based filtering or aggregation. This ensures that any malformed or non-record entries do not cause runtime errors during aggregation.

```javascript
export function buildSummary({ locatorBackfill, assets, blockers }) {
  const locatorSummary = locatorBackfill?.summary ?? {};
  const rawAssetsCount = assets.length;
  const recordAssets = assets.filter(isRecord);
  const generated = recordAssets.filter((asset) => asset.screenshot_generated);
  const questionRowRefCount = recordAssets.reduce(
    (sum, asset) => sum + (asArray(asset.referenced_by_question_rows).length),
    0,
  );
  return {
    total_governed_rows: locatorSummary.total_governed_rows ?? 0,
    exact_located_row_count: locatorSummary.exact_located_count ?? 0,
    page_located_row_count: locatorSummary.page_located_count ?? 0,
    page_or_exact_located_row_count: locatorSummary.located_row_count ?? 0,
    located_page_count: locatorSummary.located_page_count ?? 0,
    unique_ms_page_asset_count: rawAssetsCount,
    question_row_to_page_asset_ref_count: questionRowRefCount,
    duplicate_page_asset_prevented_count: questionRowRefCount - rawAssetsCount,
    generated_screenshot_count: generated.length,
    blocked_page_asset_count: blockers.length,
    total_generated_byte_size: generated.reduce((sum, asset) => sum + (asset.byte_size ?? 0), 0),
    same_page_multiple_question_exposure_count: recordAssets.filter(
      (asset) => asset.page_exposure_risk?.page_contains_other_questions,
    ).length,
    student_display_allowed_count: recordAssets.filter((asset) => asset.student_display_allowed === true).length,
    public_static_url_allowed_count: recordAssets.filter(
      (asset) => asset.asset_delivery?.public_static_url_allowed === true,
    ).length,
    pre_attempt_fetch_allowed_count: recordAssets.filter(
      (asset) => asset.asset_delivery?.pre_attempt_fetch_allowed === true,
    ).length,
    preload_in_frontend_bundle_allowed_count: recordAssets.filter(
      (asset) => asset.asset_delivery?.preload_in_frontend_bundle_allowed === true,
    ).length,
    git_committed_binary_count: 0,
    candidate_internal_asset_count: recordAssets.filter(
      (asset) => asset.student_display_posture === 'candidate_internal',
    ).length,
  };
}
```

<details>
<summary>References</summary>

1. When recomputing summary statistics from an array that may contain malformed or non-record entries, preserve the raw count of all elements for the total count, but filter the array to record-only entries before performing property-based filtering or aggregation.
</details>

